UPDATE characters SET data = json_remove(json_set(data, '$.jinxes', json('[{"name":"Boffin","align":"evil","text":"Another Minion registers as the Demon to the Boffin instead of the Cespholopod.","id":"boffin"},{"name":"Engineer","align":"good","text":"The Engineer cannot choose the Cespholopod to swap in or out.","id":"engineer"},{"name":"Exorcist","align":"good","text":"Only 1 jinxed character can be in play.","id":"exorcist"},{"name":"Farmer","align":"good","text":"If the Cespholopod kills the Farmer, a good player becomes a Farmer that night.","id":"farmer"},{"name":"Flowergirl","align":"good","text":"The Flowergirl instead learns how many times Minions voted today for their ability.","id":"flowergirl"},{"name":"Fortune Teller","align":"good","text":"Minions register as the Demon to the Fortune Teller.","id":"fortuneteller"},{"name":"Golem","align":"good","text":"If the Golem nominates a Minion, the Minion player does not die.","id":"golem"},{"name":"Grandmother","align":"good","text":"If the Cespholopod kills the Grandmother''s grandchild, the Grandmother dies tonight.","id":"grandmother"},{"name":"Hatter","align":"good","text":"The Demon cannot choose to become the Cespholopod. If the Hatter dies, the Cespholopod can only choose 1 Minion to become a different one.","id":"hatter"},{"name":"Innkeeper","align":"good","text":"If the Cespholopod would kill the player the Innkeeper chose, that player does not die.","id":"innkeeper"},{"name":"King","align":"good","text":"If the Cespholopod kills the King and the Choirboy is alive, the Choirboy wakes tonight to learn all the Minions. Minions also learn that the King is in-play (but not who they are).","id":"king"},{"name":"Magician","align":"good","text":"The Magician''s ability is replaced with: \"Each night, choose if you want to register as evil or not.\"","id":"magician"},{"name":"Marionette","align":"evil","text":"The Marionette instead neighbours a Minion, who also knows who the Marionette is.","id":"marionette"},{"name":"Mastermind","align":"evil","text":"The Mastermind''s ability activates if all other Minions are dead, and not the Cespholopod.","id":"mastermind"},{"name":"Mayor","align":"good","text":"Only 1 jinxed character can be in play.","id":"mayor"},{"name":"Monk","align":"good","text":"If the Cespholopod would kill the player the Monk chose, that player does not die.","id":"monk"},{"name":"Pit-Hag","align":"evil","text":"The Pit-Hag cannot choose the Cespholopod to swap in or out.","id":"pithag"},{"name":"Poppy Grower","align":"good","text":"The Cespholopod only start with 1 bluff. When the Poppy Grower dies, they then learn an additional 2 bluffs.","id":"poppygrower"},{"name":"Psychopath","align":"evil","text":"The Psychopath neighbours the Cespholopod and is not required to die for the Cespholopod to be vulnerable.","id":"psychopath"},{"name":"Ravenkeeper","align":"good","text":"If the Cespholopod kills the Ravenkeeper, they wake that night to use their ability.","id":"ravenkeeper"},{"name":"Sage","align":"good","text":"If the Cespholopod kills the Sage, they wake that night to learn 1 of 2 players are a particular Minion, for each in-play Minion.","id":"sage"},{"name":"Scarlet Woman","align":"evil","text":"Minions register as the Demon to the Scarlet Woman.","id":"scarletwoman"},{"name":"Slayer","align":"good","text":"Minions register as the Demon to the Slayer.","id":"slayer"},{"name":"Spy","align":"evil","text":"Only 1 jinxed character can be in play.","id":"spy"},{"name":"Summoner","align":"evil","text":"If the Cespholopod and the Summoner are both in play, the game starts with one less Minion in play. The Summoner instead chooses another player other than the Cespholopod to become a Minion of their choice, rather than a Demon. If that Minion is already in-play, a different Minion is made instead.","id":"summoner"},{"name":"Vizier","align":"evil","text":"The Vizier neighbours the Cespholopod and is not required to die for the Cespholopod to be vulnerable.","id":"vizier"},{"name":"Widow","align":"evil","text":"Only 1 jinxed character can be in play.","id":"widow"},{"name":"Tunisian","align":"good","text":"If the Cespholopod would kill the good player the Tunisian chose, that player does not die.","slug":"tunisian"},{"name":"Panacea","align":"good","text":"If the Cespholopod would kill the player the Panacea chose, that player does not die.","slug":"panacea"},{"name":"Peacemonger","align":"good","text":"The Peacemonger''s ability will instead activate if the Cespholopod didn''t kill anyone during the day.","slug":"peacemonger-scp-fragmented-veil"},{"name":"Revenant","align":"good","text":"If the Cespholopod kills the Revenant, they wake that night to use their ability.","slug":"revenant-scp-fragmented-veil"},{"name":"GOC Physics","align":"good","text":"If the Cespholopod would kill the player the GOC Physics whilst they activated their ability last night, they do not die.","slug":"goc-physics"},{"name":"Chupacabra","align":"evil","text":"If the Cespholopod is in play, the Chupacabra does not learn which players were nominated by evil & may choose any player. If that player was not nominated by evil today, they do not die.","id":"chupacabra_hblreleased"},{"name":"Fetch","align":"good","text":"The Cespholopod themselves cannot register as executed to the Fetch for their ability.","id":"fetch_hblreleased"},{"name":"Leftenent","align":"evil","text":"Minions register as the Demon to the Leftenent.","id":"leftenent_hblreleased"},{"name":"Porcher","align":"good","text":"If the Cespholopod is in-play, the Porcher ability they gain is always active, but they cannot kill with it. If the Porcher ability grants the Cespholopod ability, a Townsfolk becomes evil and registers as a Minion to the Demon, but cannot kill with that ability.","id":"porcher_hblreleased"},{"name":"Wig Snatcher","align":"good","text":"If the Cespholopod is in play & the player the Wig Snatcher chose dies by the Cespholopod, the Wig Snatcher becomes their character that night.","id":"wigsnatcher_hblreleased"},{"name":"Haberdasher","align":"good","text":"The Cespholopod is safe from losing their ability from the Haberdasher, but still cannot kill their good neighbors.","id":"haberdasher_hblreleased"},{"name":"Archivist","align":"good","text":"The Archivist can only ask questions about Minions'' abilities (between any to all) instead of the Demon''s ability.","id":"archivist_the_bootleggers_anthology"},{"name":"Fencer","align":"good","text":"Only 1 jinxed character can be in play.","id":"fencer_the_bootleggers_anthology"},{"name":"Penitent","align":"good","text":"If the Penitent dies, a Minion instead gets the choice to have their ability replaced with ''Each night*, choose a player: they die. Once per game, the Storyteller chooses who instead.''","id":"penitent_the_bootleggers_anthology"},{"name":"Carpenter","align":"evil","text":"If the Cespholopod is in play & the Carpenter would learn a ''yes'', they instead learn half of the Minion players (rounded down).","id":"carpenter_circus_music"},{"name":"Kenku","align":"good","text":"If the Cespholopod would kill the player the Kenku chose, 2 other good players instead die.","id":"kenku_circus_music"},{"name":"Cleric","align":"good","text":"The Cleric''s ability is replaced with \"If you nominate the last living Minion, they die.\".","id":"cleric_circus_music"},{"name":"Firewatcher","align":"good","text":"If the Cespholopod would kill a player the Firewatcher is targetting, the Firewatcher dies instead & the day ends.","id":"firewatcher_festival_of_lanterns"},{"name":"Singer","align":"good","text":"Minions register as the Demon to the Singer.","id":"singer_festival_of_lanterns"},{"name":"Vixin","align":"good","text":"The Vixin''s first night choice is made by the Storyteller.","id":"vixin_festival_of_lanterns"},{"name":"Buggane","align":"evil","text":"If the Cespholopod would kill a Townsfolk the Buggane is protecting, that player does not die.","id":"buggane_2tfafullcharacterlist"},{"name":"Curarist","align":"good","text":"The Curarist''s ability is replaced with \"You bring a friend. [+1 to +2 Outsiders, they neighbour a Minion]\".","id":"curarist_2tfafullcharacterlist"},{"name":"Dean","align":"good","text":"If the Cespholopod is in play, the Dean instead learns the last living Minion once they reach that condition.","id":"dean_2tfafullcharacterlist"},{"name":"Hippie","align":"good","text":"If the Cespholopod is in play, Minions don''t wake together. Only one of them wakes.","id":"hippie_2tfafullcharacterlist"},{"name":"Milkmaid","align":"good","text":"If the Cespholopod kills the Milkmaid, they wake that night to use their ability.","id":"milkmaid_2tfafullcharacterlist"},{"name":"Ornithologist","align":"good","text":"The Cespholopod player does not draw a blank token.","id":"ornithologist_2tfafullcharacterlist"},{"name":"Rat-Catcher","align":"good","text":"If the Cespholopod does not learn who the Rat-catched Minion is.","id":"ratcatcher_2tfafullcharacterlist"},{"name":"Troll","align":"good","text":"If the Cespholopod would kill the Troll, a Minion dies instead (unless the Troll is drunk).","id":"troll_2tfafullcharacterlist"},{"name":"Baker","align":"good","text":"If the Cespholopod would kill the player the Baker is protecting that night, that player does not die.","id":"baker_darkartists_stuff"},{"name":"Bloodless","align":"evil","text":"The 2nd to last living Minion to die registers as the Demon to the Bloodless","id":"bloodless_darkartists_stuff"},{"name":"Dianite","align":"good","text":"The Cespholopod does not register as evil to the Dianite.","id":"dianite_darkartists_stuff"},{"name":"Dockworker","align":"good","text":"Minions register as the Demon to the Dockworker for the execution.","id":"dockworker_darkartists_stuff"},{"name":"Fencer","align":"good","text":"If the Cespholopod kills the Fencer, the Cespholopod can die to their ability.","id":"fencer_darkartists_stuff"},{"name":"Haunt","align":"evil","text":"The Haunt''s first night choice is made by the Storyteller.","id":"haunt_darkartists_stuff"},{"name":"Houndmaster","align":"good","text":"The Houndmaster''s ability does not activate by nominating the Cespholopod.","id":"houndmaster_darkartists_stuff"},{"name":"Omen","align":"good","text":"If the Cespholopod is in play & the last Minion dies, the Omen''s ability activates on them instead of the Demon.","id":"omen_darkartists_stuff"},{"name":"Ritualist","align":"good","text":"Only 1 jinxed character can be in play.","id":"ritualist_darkartists_stuff"}]')), '$.customBoxes'), updated_at = datetime('now') WHERE slug = 'cespholopod';
